-- Reference seed (part 04.01): the feature flags (OFF by default, ON in development and test), the workflow pages in the navigation registry and in the migration tracker.
-- The adapter flag of each legacy request type is a separate flag so a type can be switched to the engine, and back, on its own.
INSERT OR IGNORE INTO core_feature_flags (key, description, default_enabled, environment, enabled, created_by, source_type)
VALUES ('ff.eng.p0401', 'Part 04.01 workflow engine core: definitions, instances, tasks, the sample document type', 0, NULL, 0, 'migration', 'reference_seed');
