SELECT 'ff.eng.p0401', 'Part 04.01 workflow engine core: definitions, instances, tasks, the sample document type', 0, env.name, 1, 'migration', 'reference_seed'
FROM (SELECT 'development' AS name UNION ALL SELECT 'test') AS env;
